namespace MapStudio.Core.Tests;

public sealed class OmsiTextureAssetPathResolverTests
{
    [Fact]
    public void ResolvesSceneryTextureInsidePack()
    {
        var root =
            CreateTempRoot();

        try
        {
            var objectDirectory =
                Path.Combine(
                    root,
                    "Sceneryobjects",
                    "Pack");

            var modelDirectory =
                Path.Combine(
                    objectDirectory,
                    "model");

            var textureDirectory =
                Path.Combine(
                    objectDirectory,
                    "Texture");

            Directory.CreateDirectory(
                modelDirectory);
            Directory.CreateDirectory(
                textureDirectory);

            var objectPath =
                Path.Combine(
                    objectDirectory,
                    "house.sco");

            var meshPath =
                Path.Combine(
                    modelDirectory,
                    "house.o3d");

            var texturePath =
                Path.Combine(
                    textureDirectory,
                    "wall.dds");

            File.WriteAllText(
                objectPath,
                string.Empty);
            File.WriteAllText(
                meshPath,
                string.Empty);
            File.WriteAllBytes(
                texturePath,
                [1, 2, 3]);

            Assert.True(
                OmsiTextureAssetPathResolver
                    .TryResolveSceneryTexture(
                        root,
                        objectPath,
                        meshPath,
                        "wall.dds",
                        out var resolved));

            Assert.Equal(
                Path.GetFullPath(
                    texturePath),
                resolved);
        }
        finally
        {
            Directory.Delete(
                root,
                recursive: true);
        }
    }

    [Fact]
    public void ResolvesSplineTextureInsidePack()
    {
        var root =
            CreateTempRoot();

        try
        {
            var splineDirectory =
                Path.Combine(
                    root,
                    "Splines",
                    "Pack");

            var textureDirectory =
                Path.Combine(
                    splineDirectory,
                    "Texture");

            Directory.CreateDirectory(
                textureDirectory);

            var splinePath =
                Path.Combine(
                    splineDirectory,
                    "road.sli");

            var texturePath =
                Path.Combine(
                    textureDirectory,
                    "road.tga");

            File.WriteAllText(
                splinePath,
                string.Empty);
            File.WriteAllBytes(
                texturePath,
                [1, 2, 3]);

            Assert.True(
                OmsiTextureAssetPathResolver
                    .TryResolveSplineTexture(
                        root,
                        splinePath,
                        "road.tga",
